#!/usr/bin/env python3
"""Assign the six requested visual wheel styles without changing physics or source recipes.
The recovered shop rows have no six-style field. This is explicit native curation,
based on source wheel families, geometry and reviewed source composition sheets.
"""
from pathlib import Path
import json,re,collections
G=Path(__file__).resolve().parents[1];recipes=json.loads((G.parent/'evidence/merged/rims.json').read_text())['rims'];rows=[]
labels=['TOUTES','OFFROAD','TUNER','MUSCLE','DRAG','LUXURY','HYPER']
for r in recipes:
 n=r['name'].lower();sid=r['source_id'];reason='Japanese/European street and track spoke family';style=2
 if any(t in n for t in ['weld','drag','alum star','magnum','race star']) or n in ['et','etpro']:style=4;reason='Drag-racing wheel family, light centres and drag steelies'
 elif any(t in n for t in ['22b oem','c1 vent','turbo fan','turbo-r','turbo4','15fiftytwo outlaw']):style=1;reason='Rally/offroad-inspired wheel or ventilated rally disc'
 elif any(t in n for t in ['usa racing','vn427','vn501','vn471','rot steel']) or re.match(r'ar\d',n) or n=='sleepers':style=3;reason='American classic/muscle wheel family'
 elif any(t in n for t in ['vip','sl dub','vvs','wvs','bazreia','minerva','lxz','waffe','hci md1','diamond glass','stance','sl gens','sl ratz','voss deep']) or n in ['bullets','worx equip xl']:style=5;reason='VIP/luxury, large polished face or deep-dish luxury design'
 elif any(t in n for t in ['carbon','bbx f1','bbx fir','bbx re-mg','forged','av form','av sport','voss concepts','advant gt','rs7 ','rs13 ','rs16','s107','vx tens','vx eleven','vx concave','vx advent','advent super','bladez 21']):style=6;reason='Modern forged, aero or lightweight supercar/hypercar-inspired design'
 rows.append({'source_id':sid,'name':r['name'],'style':labels[style],'style_id':style,'reason':reason,'spoke_count':r['fields']['count'],'lip':r['fields']['lip'],'spoke':r['fields']['spoke']})
h=['// Generated by classify_rims.py. Visual categories, no performance effect.','#pragma once','#include "rims.hpp"','#include "catalog_review.hpp"','namespace pcr {','enum class RimStyle { All,Offroad,Tuner,Muscle,Drag,Luxury,Hyper };','inline constexpr const char* RimStyleLabels[]={'+','.join(json.dumps(s) for s in labels)+'};','struct RimStyleEntry {int sourceId;RimStyle style;};','inline constexpr RimStyleEntry RimStyleCatalog[]={']+['{'+str(r['source_id'])+',RimStyle::'+['All','Offroad','Tuner','Muscle','Drag','Luxury','Hyper'][r['style_id']]+'},' for r in rows]+['};','inline RimStyle rimStyleOf(int id){auto r=findRim(canonicalRimId(id));if(!r)return RimStyle::Tuner;auto at=std::lower_bound(std::begin(RimStyleCatalog),std::end(RimStyleCatalog),r->sourceId,[](const auto& row,int key){return row.sourceId<key;});return at!=std::end(RimStyleCatalog)&&at->sourceId==r->sourceId?at->style:RimStyle::Tuner;}','inline const char* rimStyleLabel(RimStyle style){return RimStyleLabels[std::clamp(int(style),0,6)];}','}'];(G/'src/rim_styles.hpp').write_text('\n'.join(h)+'\n')
report={'method':'Native visual curation; recovered source shop rows do not encode these six style categories. Original recipe IDs and source wheel families remain intact.','categories':labels[1:],'base_recipe_counts':dict(collections.Counter(r['style'] for r in rows)),'variants_inherit_base_style':True,'physics_changed':False,'rims':rows};(G/'rim-styles.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps(report['base_recipe_counts']))
